// Hand-rolled Zod-style validator. Collects ALL violations, not just the
// first, and never lets a malformed request reach the vector store or LLM.
const cfg = $input.first().json;
const body = cfg.body || {};

const errors = [];

function isNonEmptyString(v) { return typeof v === 'string' && v.trim().length > 0; }

if (!isNonEmptyString(body.query)) {
  errors.push({ field: 'query', message: 'query is required and must be a non-empty string' });
} else if (body.query.length > (cfg.maxQueryLength || 2000)) {
  errors.push({ field: 'query', message: `query exceeds max length of ${cfg.maxQueryLength || 2000}` });
}

if (!isNonEmptyString(body.conversationId)) {
  errors.push({ field: 'conversationId', message: 'conversationId is required and must be a non-empty string' });
}

if (!isNonEmptyString(body.tenantId)) {
  errors.push({ field: 'tenantId', message: 'tenantId is required and must be a non-empty string' });
}

const namespace = body.namespace || cfg.vectorNamespaceDefault;
const allowed = cfg.allowedNamespaces || [];
if (!allowed.includes(namespace)) {
  errors.push({ field: 'namespace', message: `namespace must be one of: ${allowed.join(', ')}` });
}

return [{
  json: {
    ...cfg,
    query: isNonEmptyString(body.query) ? body.query.trim() : '',
    conversationId: body.conversationId || null,
    tenantId: body.tenantId || null,
    namespace,
    isValid: errors.length === 0,
    validationErrors: errors
  }
}];

const crypto = require('crypto');
const d = $input.first().json;
const normalizedQuery = d.query.toLowerCase().trim().replace(/\s+/g, ' ');
const raw = `${d.tenantId}::${d.namespace}::${normalizedQuery}`;
const cacheKey = 'rag:' + crypto.createHash('sha256').update(raw).digest('hex');

return [{ json: { ...d, normalizedQuery, cacheKey, requestStartedAt: new Date().toISOString() } }];

// Second Zod-style validation boundary — on the AGENT'S output this time.
// Never forward malformed model output to Next.js.
const ctx = $('Code - Build Cache Key').first().json;
const response = $input.first().json;

function safeFallback(reason) {
  return {
    answer: "I don't have enough information to answer that confidently right now.",
    citations: [],
    groundedness: 'ungrounded',
    confidencePercent: 0,
    _fallbackReason: reason
  };
}

let parsed;
try {
  const raw = String(response.output || response.text || response.response || '{}').replace(/```json|```/g, '').trim();
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = safeFallback('Failed to parse agent JSON output.');
}

const errors = [];
if (typeof parsed.answer !== 'string' || parsed.answer.trim().length === 0) errors.push('answer missing or not a string');
if (!Array.isArray(parsed.citations)) errors.push('citations missing or not an array');
else if (!parsed.citations.every(c => c && typeof c.source === 'string' && typeof c.snippet === 'string')) errors.push('citations entries malformed');
if (!['grounded', 'partial', 'ungrounded'].includes(parsed.groundedness)) errors.push('groundedness invalid');
if (typeof parsed.confidencePercent !== 'number' || parsed.confidencePercent < 0 || parsed.confidencePercent > 100) errors.push('confidencePercent invalid');

if (errors.length > 0) {
  parsed = safeFallback('Agent output failed schema validation: ' + errors.join('; '));
}

const latencyMs = Date.now() - new Date(ctx.requestStartedAt).getTime();

return [{
  json: {
    conversationId: ctx.conversationId,
    tenantId: ctx.tenantId,
    namespace: ctx.namespace,
    query: ctx.query,
    cacheKey: ctx.cacheKey,
    cacheTtlSeconds: ctx.cacheTtlSeconds,
    nextjsRevalidateUrl: ctx.nextjsRevalidateUrl,
    nextjsRevalidateSecret: ctx.nextjsRevalidateSecret,
    latencyMs,
    cacheHit: false,
    ...parsed
  }
}];

// A failed callback to Next.js must never surface as a user-facing error —
// the chat response already succeeded and was already sent. Just log it.
const d = $input.first().json;
const failed = !!(d.error || d.errorMessage);

if (failed) {
  console.warn('Next.js revalidation callback failed (non-fatal):', d.error || d.errorMessage);
}

return [{ json: { ...d, revalidationSucceeded: !failed } }];
